import os
os.makedirs('programs',exist_ok=True)
p='programs/task-f91ce6bb.py'
s='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    rows = {r for r,c in markers if c in (0,w-1)}
    cols = {c for r,c in markers if r in (0,h-1)}
    for r in rows:
        for c in range(w): out[r][c] = 1
    for c in cols:
        for r in range(h): out[r][c] = 1
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                x,y=stack.pop(); comp.append((x,y))
                for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:
                        seen.add((a,b)); stack.append((a,b))
            if any(x in rows or y in cols for x,y in comp):
                for x,y in comp: out[x][y]=1
    return out
'''
open(p,'w').write(s)
